def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent's previous moves
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    # Last few moves
    last_my, last_opp = history[-1]

    # Detect opponent patterns
    # Check if opponent always cooperates
    if opp_d == 0:
        return 'C'

    # Check if opponent always defects
    if opp_c == 0:
        return 'D'

    # Count runs / detect alternating
    alter = True
    for i in range(1, min(n, 10)):
        if history[-i][1] == history[-i-1][1]:
            alter = False
            break

    # Detect if opponent is mostly cooperative
    coop_rate = opp_c / n if n > 0 else 0

    # Detect reciprocation: did opponent mirror my previous move?
    mirror_matches = 0
    mirror_total = 0
    for i in range(1, n):
        if history[i][1] == history[i-1][0]:
            mirror_matches += 1
        mirror_total += 1

    mirror_score = mirror_matches / mirror_total if mirror_total > 0 else 0

    # If opponent mirrors strongly, cooperate to keep mutual C
    if mirror_score > 0.7 and n >= 4:
        return 'C'

    # If opponent is retaliatory (defects after we defect)
    # Check: last round we defected, did opponent defect?
    if n >= 2:
        if history[-2][0] == 'D' and history[-1][1] == 'D':
            # Opponent retaliates. If we cooperate now, will they?
            if n >= 3 and history[-3][0] == 'C' and history[-2][1] == 'C':
                return 'C'
            return 'C'

    # Late game exploitation: last few rounds, defect if ahead
    remaining = 100 - n
    if remaining <= 3:
        # Defect in last rounds if opponent likely to cooperate or mixed
        if coop_rate > 0.4:
            return 'D'
        return 'D'

    # Early game: cooperate to establish trust
    if n <= 3:
        return 'C'

    # Tit-for-tat-like with forgiveness
    if last_opp == 'D':
        # Opponent defected last. Retaliate but occasionally forgive.
        # Count consecutive opponent defections
        consec_d = 0
        for i in range(n-1, -1, -1):
            if history[i][1] == 'D':
                consec_d += 1
            else:
                break

        if consec_d >= 3:
            # Heavy retaliation phase
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if consec_d == 2:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Single defection: retaliate once
        return 'D'
    else:
        # Opponent cooperated. Cooperate back, but probe occasionally.
        if rng.random() < 0.05 and n < 90:
            return 'D'
        return 'C'
